        nside = 32
        lons = np.array([45.0, 45.0, 45.0])
        lats = np.array([30.0, 30.0, 30.0])
        ids = compute_healpix_ids_from_lonlat(nside, lons, lats)
        assert ids[0] == ids[1] == ids[2]
    
